uniform sampler2D csNoise;
float csTN(vec2 p) { return texture(csNoise, p / 32.0).r; }


uniform sampler2D cbRand;


void ruWear(float w, vec3 p, vec3 n, float rotOn, float charOn, float mossOn, inout vec3 colour, inout float rough, inout float height) {
  if (w <= 0.0) return;
  // the nearness shaken by noise, so each band's edge is ragged and no two breaks wear alike
  vec2 q = p.xz + p.y * 0.37;
  float e = w + (kfbm4(q * 2.3) - 0.5) * 0.45;
  // rain stains: streaks running down the slope, strongest a little off the break where water ran in over the edge
  float streak = kfbm4(vec2(q.x * 9.0, p.y * 1.2));
  float stain = smoothstep(0.05, 0.45, e) * smoothstep(0.4, 0.7, streak);
  colour *= 1.0 - 0.35 * stain;
  // rot: darker, greyer and rougher nearer the break, the grain softened
  float rot = smoothstep(0.25, 0.7, e) * rotOn;
  vec3 grey = vec3(dot(colour, vec3(0.3, 0.5, 0.2)));
  colour = mix(colour, mix(grey, vec3(0.06, 0.05, 0.04), 0.45), rot * 0.85);
  rough = mix(rough, 0.95, rot);
  height *= 1.0 - 0.6 * rot;
  // moss on what faces up, in patches, between the rot and the char
  float up = smoothstep(0.25, 0.75, n.y);
  float moss = up * smoothstep(0.3, 0.55, e) * smoothstep(0.95, 0.75, e) * smoothstep(0.45, 0.65, kfbm(q * 4.1 + 3.3)) * mossOn;
  colour = mix(colour, mix(vec3(0.05, 0.08, 0.02), vec3(0.12, 0.16, 0.04), kn(q * 37.0)), moss);
  height += 0.002 * moss * kn(q * 61.0);
  // the char at the very edge: black, crazed into the squares wood burns into, the cracks deeper
  float burnt = smoothstep(0.72, 0.9, e) * charOn;
  float id, edge;
  kvor(q * 26.0, id, edge);
  float crack = smoothstep(0.08, 0.0, edge) * kfade(0.03);
  colour = mix(colour, vec3(0.025, 0.022, 0.02) * (0.7 + 0.6 * id), burnt);
  rough = mix(rough, 0.9, burnt);
  height = mix(height, 0.0015 * (1.0 - crack) - 0.0015, burnt);
}


// the pixel's size on the ground (m), set before any sampling
float cbFp = 0.001;
// noise at the place p (m) with features 1/f m across, blurred to no finer than the pixel: csNoise has 8 texels to a
// unit, so f units to the metre is 8 f texels to the metre
float cbN(vec2 p, float f) { return textureLod(csNoise, p * f / 32.0, log2(max(cbFp * f * 8.0, 1.0))).r; }
// the four random numbers of the cobble cell c
vec4 cbR(ivec2 c) {
  ivec2 s = ivec2(int(p_seed) * 37, int(p_seed) * 91);
  return texelFetch(cbRand, (c + s) & 255, 0);
}
// a cell's seed, in cells from its corner
vec2 cbSeed(vec4 r) { return 0.5 + (r.xy - 0.5) * p_jitter; }

// the cobble at the place q (metres on the ground): how far in from its edge (d, m), how far from its seed (r, m),
// its numbers, its seed's place (m). The nine seeds round the place are read once; the nearest is the cobble, and
// its edge is the nearest of the lines halfway to the other eight, joined by a smooth minimum Corner round wide,
// so the cobble's corners are rounded, not a polygon's.
struct CbCell { float d; float r; vec4 rnd; vec2 middle; };
CbCell cbCell(vec2 q) {
  vec2 sc = p_size * vec2(p_stretch, 1.0);
  vec2 x = q / sc;
  vec2 n = floor(x), f = x - n;
  ivec2 ni = ivec2(n);
  vec2 o[9];
  vec4 rr[9];
  float md = 8.0;
  int mk = 4;
  for (int j = 0; j < 3; j++) for (int i = 0; i < 3; i++) {
    vec4 r = cbR(ni + ivec2(i - 1, j - 1));
    vec2 rel = vec2(i - 1, j - 1) + cbSeed(r) - f;
    rr[j * 3 + i] = r;
    o[j * 3 + i] = rel;
    float d = dot(rel * sc, rel * sc);
    if (d < md) { md = d; mk = j * 3 + i; }
  }
  vec2 mr = o[mk];
  vec2 a = mr * sc;
  float kk = max(p_corner, 1e-4);
  float bd = 8.0;
  for (int k = 0; k < 9; k++) {
    if (k == mk) continue;
    vec2 b = o[k] * sc;
    bd = min(bd, dot(0.5 * (a + b), normalize(b - a)));
  }
  // the smooth minimum, worked from the hard one so exp never overflows
  float sum = 0.0;
  for (int k = 0; k < 9; k++) {
    if (k == mk) continue;
    vec2 b = o[k] * sc;
    sum += exp(-(dot(0.5 * (a + b), normalize(b - a)) - bd) / kk);
  }
  CbCell C;
  C.d = bd - kk * log(sum);
  C.r = length(a);
  C.rnd = rr[mk];
  C.middle = q + a;
  return C;
}

struct CbS { float h; float d; float t; vec4 rnd; float stone; float moss; float mossH; };
// the path's height at q (0 its proudest, down to the sand's depth): the cobble's face domed, worn flat at its top,
// rounded and chipped at its edge, sunk and tilted in its bed, roughened; the sand between
CbS cbSample(vec2 q) {
  CbCell C = cbCell(q);
  float warp = (cbN(q + C.rnd.zw * 50.0, 22.0) - 0.5) * 3.0 * p_chip;
  float d = C.d - 0.5 * p_joint + warp;
  // 0 at the cobble's seed, 1 at its edge
  float t = clamp(C.r / max(C.r + max(C.d, 0.0), 1e-4), 0.0, 1.0);
  float tf = max(t - p_flat, 0.0) / max(1.0 - p_flat, 1e-3);
  vec2 lean = (vec2(C.rnd.z, C.rnd.w) - 0.5) * 2.0;
  float hs = -p_dome * tf * tf
             - p_edgeDrop * pow(1.0 - smoothstep(0.0, p_edgeRound, d), 2.0)
             - p_sink * (0.5 + 0.5 * cos(C.rnd.z * 40.0)) - p_sink * 0.25
             + dot(lean, (q - C.middle) / p_size) * p_tilt - p_tilt
             + (cbN(q + C.rnd.xy * 37.0, 45.0) - 0.5) * 2.0 * p_detail - 0.5 * p_detail;
  float hm = -p_recess + (cbN(q, 160.0) - 0.5) * 0.006;
  CbS S;
  S.stone = (d > 0.0 && hs > hm) ? 1.0 : 0.0;
  float base = d > 0.0 ? max(hs, hm) : hm;
  // the moss: a layer over the cobbles and the sand, in patches Moss patch size across. Where it grows: the joints
  // first, then the cobbles' edges, then (Moss on tops) over their faces. It fills the joints toward the cobbles'
  // shoulders and lies Moss depth thick in lumpy cushions over the rest.
  float spread = cbN(q + 11.3, 1.0 / p_mossScale) * 0.65 + cbN(q + 3.7, 3.0 / p_mossScale) * 0.35;
  float edge = 1.0 - smoothstep(0.0, p_edgeRound * 2.0, d);
  float want = S.stone > 0.5 ? mix(p_mossTop, 1.0, edge * 0.8) : 1.0;
  float thr = 1.0 - p_mossCover;
  S.moss = smoothstep(thr - 0.12, thr + 0.12, spread * (0.55 + 0.45 * want) + 0.25 * want - 0.25);
  float lump = cbN(q + 5.1, 90.0) * 0.6 + cbN(q + 9.9, 30.0) * 0.4;
  float fill = (1.0 - S.stone) * 0.45 * p_recess * smoothstep(0.0, p_edgeRound, -d + 0.004);
  S.mossH = S.moss * (p_mossDepth * (0.45 + 0.75 * lump) + fill);
  S.h = base - p_mossDepth + S.mossH;
  S.d = d;
  S.t = t;
  S.rnd = C.rnd;
  return S;
}










// the distance from p to the segment a-b
float rgSeg(vec2 p, vec2 a, vec2 b) {
  vec2 pa = p - a, ba = b - a;
  return length(pa - ba * clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0));
}
// a rune: three strokes between points of a 3 by 3 grid, chosen by its number; q in the rune's box, 0 to 1 each way
float rgRune(vec2 q, float id) {
  float d = 9.0;
  for (int s = 0; s < 3; s++) {
    float h = kh(vec2(id, float(s) * 3.7));
    float g = kh(vec2(id * 1.3, float(s) * 5.1 + 1.0));
    vec2 a = vec2(floor(h * 3.0), floor(fract(h * 7.0) * 3.0)) * 0.5;
    vec2 b = vec2(floor(g * 3.0), floor(fract(g * 7.0) * 3.0)) * 0.5;
    if (length(a - b) < 0.1) b = vec2(1.0) - a;
    d = min(d, rgSeg(q, a, b));
  }
  return d;
}








    float hbCurve(vec3 n) {
      vec3 dx = dFdx(n), dy = dFdy(n);
      return clamp(length(dx) + length(dy), 0.0, 1.0);
    }








void look_0(inout Look k) {
  p_size = texelFetch(lookSettings, ivec2(0, 0), 0).r;
  p_jitter = texelFetch(lookSettings, ivec2(1, 0), 0).r;
  p_stretch = texelFetch(lookSettings, ivec2(2, 0), 0).r;
  p_joint = texelFetch(lookSettings, ivec2(3, 0), 0).r;
  p_seed = texelFetch(lookSettings, ivec2(4, 0), 0).r;
  p_dome = texelFetch(lookSettings, ivec2(5, 0), 0).r;
  p_flat = texelFetch(lookSettings, ivec2(6, 0), 0).r;
  p_corner = texelFetch(lookSettings, ivec2(7, 0), 0).r;
  p_edgeRound = texelFetch(lookSettings, ivec2(8, 0), 0).r;
  p_edgeDrop = texelFetch(lookSettings, ivec2(9, 0), 0).r;
  p_chip = texelFetch(lookSettings, ivec2(10, 0), 0).r;
  p_sink = texelFetch(lookSettings, ivec2(11, 0), 0).r;
  p_tilt = texelFetch(lookSettings, ivec2(12, 0), 0).r;
  p_detail = texelFetch(lookSettings, ivec2(13, 0), 0).r;
  p_recess = texelFetch(lookSettings, ivec2(14, 0), 0).r;
  p_valueVar = texelFetch(lookSettings, ivec2(15, 0), 0).r;
  p_warm = texelFetch(lookSettings, ivec2(16, 0), 0).r;
  p_dark = texelFetch(lookSettings, ivec2(17, 0), 0).r;
  p_fleck = texelFetch(lookSettings, ivec2(18, 0), 0).r;
  p_polish = texelFetch(lookSettings, ivec2(19, 0), 0).r;
  p_dirt = texelFetch(lookSettings, ivec2(20, 0), 0).r;
  p_mossCover = texelFetch(lookSettings, ivec2(21, 0), 0).r;
  p_mossTop = texelFetch(lookSettings, ivec2(22, 0), 0).r;
  p_mossDepth = texelFetch(lookSettings, ivec2(23, 0), 0).r;
  p_mossScale = texelFetch(lookSettings, ivec2(24, 0), 0).r;
  p_wet = texelFetch(lookSettings, ivec2(25, 0), 0).r;
  p_grey = texelFetch(lookSettings, ivec2(26, 0), 0).rgb;
  p_brown = texelFetch(lookSettings, ivec2(27, 0), 0).rgb;
  p_sand = texelFetch(lookSettings, ivec2(28, 0), 0).rgb;
  p_mossDark = texelFetch(lookSettings, ivec2(29, 0), 0).rgb;
  p_mossLight = texelFetch(lookSettings, ivec2(30, 0), 0).rgb;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

  // the path's top: laid on the ground; any other face laid along its height
  bool top = vLookWN.y > 0.7;
  vec2 q;
  if (top) {
    q = vec2(vLookWorld.x, -vLookWorld.z);
  } else {
    vec3 n = normalize(vLookWN);
    vec3 along = normalize(vec3(-n.z, 0.0, n.x) + vec3(1e-5, 0.0, 0.0));
    q = vec2(dot(vLookWorld, along), vLookWorld.y);
  }
  vec2 fw = fwidth(q);
  float fp = max(max(fw.x, fw.y), 1e-6);
  cbFp = fp;
  CbS S = cbSample(q);

  // the cobble's colour: grey to brown by its own number, its lightness, a share of dark ones, flecks and mottling;
  // its worn top lighter and smoother, its edge dirtier
  vec4 R = S.rnd;
  float val = 1.0 + (R.x - 0.5) * 2.0 * p_valueVar;
  if (R.y < p_dark) val *= 0.55;
  vec3 stoneC = mix(p_grey, p_brown, clamp(R.w * p_warm * 2.0, 0.0, 1.0)) * val;
  float fl = cbN(q + R.xy * 91.0, 260.0);
  stoneC *= 1.0 + (smoothstep(0.6, 0.7, fl) * 0.6 - smoothstep(0.6, 0.7, 1.0 - fl) * 0.35) * p_fleck;
  stoneC *= 1.0 + (cbN(q + R.zw * 13.0, 12.0) - 0.5) * 0.45;
  float worn = (1.0 - smoothstep(0.0, 0.7, S.t)) * p_polish;
  stoneC *= 1.0 + 0.18 * worn;
  float edgeDirt = (1.0 - smoothstep(0.0, p_edgeRound * 1.6, S.d)) * p_dirt;
  stoneC *= 1.0 - 0.4 * edgeDirt;
  // the sand: its grains, darker in the joint's bottom
  vec3 sandC = p_sand * (0.7 + 0.6 * cbN(q, 300.0)) * (1.0 - 0.25 * p_dirt);
  float sm = S.stone * smoothstep(-fp, fp, S.d);
  vec3 col = mix(sandC, stoneC, sm);
  // the moss layer: dark to light green, lighter where its cushions stand up and catch the light, its thin fringe
  // letting the stone or sand under it show through
  float mossM = smoothstep(0.0, 0.6, S.moss);
  float lumpC = cbN(q + 5.1, 90.0);
  vec3 mossC = mix(p_mossDark, p_mossLight, clamp(cbN(q + 2.3, 2.0 / p_mossScale) * 1.4 - 0.2, 0.0, 1.0));
  mossC *= 0.7 + 0.6 * lumpC;
  col = mix(col, mossC, mossM);
  // the cavity: the sand darker toward the cobbles, a cobble's edge darker as it rounds down; the moss's own,
  // its cushions' hollows, over them
  float aoM = mix(0.45, 0.85, smoothstep(0.0, 0.6 * p_joint + 0.006, -S.d));
  float aoS = mix(0.6, 1.0, smoothstep(0.0, p_edgeRound * 1.4, S.d));
  float ao = mix(aoM, aoS, sm);
  k.ao = mix(ao, 0.7 + 0.3 * lumpC, mossM);
  k.aoDirect = 0.35;
  float rough = mix(0.97, mix(0.82, 0.5, worn), sm);
  rough = mix(rough, 1.0, mossM);
  // wet: the low places hold it first, darker and glossy; at full wet everything is
  float low = 1.0 - smoothstep(-p_recess - p_mossDepth - 0.004, -p_mossDepth - 0.004, S.h);
  float wetM = clamp(p_wet * 1.6 - (1.0 - low) * (1.0 - p_wet) * 1.6, 0.0, 1.0);
  col *= mix(1.0, 0.55, wetM);
  k.rough = mix(rough, 0.12, wetM);

  if (lookView > 0.5 && lookView < 1.5) col = mix(vec3(0.5), R.xyz, sm);
  if (lookView > 1.5 && lookView < 2.5) col = vec3((S.h + p_recess + p_mossDepth) / (p_recess + p_mossDepth));
  k.colour = col;
  // the relief as a height, bent into the normal by the pixel's neighbours; flat on a face that is not the top
  k.height = top ? S.h : 0.0;

}

void look_1(inout Look k) {
  p_stColour = texelFetch(lookSettings, ivec2(0, 1), 0).rgb;
  p_stMetal = texelFetch(lookSettings, ivec2(1, 1), 0).r;
  p_stRough = texelFetch(lookSettings, ivec2(2, 1), 0).r;
  p_stOil = texelFetch(lookSettings, ivec2(3, 1), 0).r;
  p_stOilColour = texelFetch(lookSettings, ivec2(4, 1), 0).rgb;
  p_stOilBrown = texelFetch(lookSettings, ivec2(5, 1), 0).rgb;
  p_stOilSize = texelFetch(lookSettings, ivec2(6, 1), 0).r;
  p_stOilRough = texelFetch(lookSettings, ivec2(7, 1), 0).r;
  p_stFinPitch = texelFetch(lookSettings, ivec2(8, 1), 0).r;
  p_stFinShare = texelFetch(lookSettings, ivec2(9, 1), 0).r;
  p_stFinDepth = texelFetch(lookSettings, ivec2(10, 1), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float brush = kn(vec2(uv.x * 4.0, uv.y * 900.0) + seed) * kfade(0.002);
    float wear = kfbm(uv * 3.0 + seed);
    vec3 stC = p_stColour * (0.9 + 0.12 * brush) * (0.9 + 0.15 * wear);
    float stM = p_stMetal;
    float stR = p_stRough + 0.15 * brush + 0.1 * wear;
    float stH = 0.00005 * brush;
    // fins: a rounded ridge of share stFinShare in each pitch along s3.x, the groove between them the depth down and
    // dark (the normal they bend is worked out below); fading to the fins' mean where a pitch is under a few pixels
    float stOn = step(0.5, s3.y);
    float stFade = kfade(p_stFinPitch * 4.0);
    float stF = fract(s3.x / p_stFinPitch);
    float stRidge = smoothstep(1.0 - 2.0 * p_stFinShare, 1.0, 0.5 + 0.5 * cos(6.28318 * stF));
    // far off, the fins' mean: the ridges' share lit, the rest groove
    float stShade = mix(p_stFinShare, stRidge, stFade);
    stC *= mix(1.0, 0.55 + 0.45 * stShade, stOn);
    // burnt castor oil: blotches and runs of a brown-black varnish; thick (glossy, brown in its highlight) or thin
    float stBlot = kfbm(uv * p_stOilSize + seed * 1.7);
    float stRun = kn(vec2(uv.x * p_stOilSize * 0.6, uv.y * p_stOilSize * 9.0) + seed + 11.0);
    float stThick = smoothstep(0.35, 0.75, 0.65 * stBlot + 0.35 * stRun);
    float stO = clamp(p_stOil * (0.75 + 0.35 * stThick), 0.0, 1.0);
    vec3 stOilC = mix(p_stOilColour, p_stOilBrown, stThick * (0.5 + 0.5 * kn(uv * 60.0 + seed)));
    stC = mix(stC, stOilC * mix(1.0, 0.6 + 0.4 * stShade, stOn), stO);
    stM = mix(stM, 0.12, stO);
    stR = mix(stR, mix(0.75, p_stOilRough, stThick), stO);
    stH += p_stOil * 0.00004 * stThick;
    k.colour = stC;
    k.metal = stM;
    k.rough = stR;
    k.height = stH;
    if (stOn > 0.5) {
      // the fins bend the normal from their profile's slope worked out exactly, not from the pixels' neighbours (whose
      // steps break thin rings into dots): the way s3.x grows across the surface, in the view's ways, from its change
      // between pixels (it is even across a face, so this is clean), times the profile's slope along it
      vec3 stN = normalize(vNormal);
      vec3 stPx = dFdx(-vViewPosition), stPy = dFdy(-vViewPosition);
      vec3 stR1 = cross(stPy, stN), stR2 = cross(stN, stPx);
      float stDet = dot(stPx, stR1);
      vec3 stG = (dFdx(s3.x) * stR1 + dFdy(s3.x) * stR2) / (abs(stDet) > 1e-14 ? stDet : 1e-14);
      float stPhi = 6.28318 * stF;
      float stA = 1.0 - 2.0 * p_stFinShare;
      float stT = clamp((0.5 + 0.5 * cos(stPhi) - stA) / (1.0 - stA), 0.0, 1.0);
      float stSlope = p_stFinDepth * 6.0 * stT * (1.0 - stT) / (1.0 - stA) * (-0.5 * sin(stPhi) * 6.28318 / p_stFinPitch);
      k.normal = normalize(stN - stFade * stSlope * stG);
      k.ownNormal = true;
    }

}

void look_2(inout Look k) {
  p_tint = texelFetch(lookSettings, ivec2(0, 2), 0).rgb;
  p_contrast = texelFetch(lookSettings, ivec2(1, 2), 0).r;
  p_metres = texelFetch(lookSettings, ivec2(2, 2), 0).r;
  t_col = 0;
  t_nrm = 1;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

  // each part on its own patch of the pictures, from its thing's and its part's numbers
  vec2 kitPatch = vec2(fract(vLookInfo.y * 0.61803 + vLookInfo.z * 0.137) * 37.0, fract(vLookInfo.y * 0.75488 + vLookInfo.z * 0.291) * 23.0);
  vec2 tuv = uv / p_metres + kitPatch;
  vec3 picC = picColour(t_col, tuv, 1.0 / p_metres);
  float kitL = dot(picC, vec3(0.2126, 0.7152, 0.0722)) / picMean(t_col);
  vec3 kitN = picData(t_nrm, tuv, 1.0 / p_metres).xyz * 2.0 - 1.0;
  float kitSteep = 1.0 - clamp(kitN.z, 0.0, 1.0);
  float kitCav = clamp(smoothstep(0.05, 0.4, kitSteep) * 0.7 + smoothstep(0.7, 0.35, kitL) * 0.3, 0.0, 1.0);
  float kitBend = length(fwidth(wn)) / max(length(fwidth(wp)), 1e-5);
  float kitEdge = smoothstep(20.0, 70.0, kitBend) * (0.6 + 0.4 * kn(uv * 40.0 + seed));
  float kitUp = smoothstep(0.55, 0.95, wn.y);
  float kitDamp = 1.0 - smoothstep(0.0, 0.35 + 0.3 * kn(wp.xz * 2.0), wp.y);
  float kitMoss = clamp(smoothstep(0.55, 0.8, kfbm4(uv * 2.3 + seed * 1.7)) * (kitUp * 0.7 + kitDamp * 0.5) * (0.4 + kitCav), 0.0, 1.0) * 0.8;
  float kitV = 1.0 + (kh1(seed + 0.37) - 0.5) * 0.3;
  float kitWarm = (kh1(seed + 5.1) - 0.5) * 0.5;
  float kitMott = 1.0 + (kfbm4(uv * 1.3 + seed) - 0.5) * 0.35;
  vec3 kitC = p_tint * mix(1.0, kitL, p_contrast) * kitV * kitMott * vec3(1.0 + 0.16 * kitWarm, 1.0 + 0.02 * kitWarm, 1.0 - 0.2 * kitWarm);
  kitC *= mix(1.0, 0.75, kitCav);
  kitC = mix(kitC, kitC * vec3(0.8, 0.74, 0.64), kitCav * 0.6);
  kitC *= 1.0 - 0.35 * kitDamp;
  kitC = mix(kitC, min(kitC * 1.45 + 0.03, vec3(1.0)), kitEdge * (1.0 - kitCav));
  kitC = mix(kitC, vec3(0.05, 0.075, 0.02) * (0.7 + 0.6 * kitL), kitMoss);
  k.colour = kitC;
  // the roughness from the same: the cavity and the moss rougher, the worn edges smoother
  k.rough = clamp(0.8 + 0.18 * kitCav + 0.2 * kitMoss - 0.22 * kitEdge, 0.5, 1.0);
  // the relief: the normal picture, and over it the rock's lightness as a height, its dark sunk
  k.nts = kitN;
  k.height = (kitL - 1.0) * 0.003;
  // the cavity shades the light that comes from everywhere
  k.ao = mix(1.0, 0.7, kitCav);

}

void look_3(inout Look k) {
  p_repeat = texelFetch(lookSettings, ivec2(0, 3), 0).r;
  p_tmRot = texelFetch(lookSettings, ivec2(1, 3), 0).r;
  p_tmChar = texelFetch(lookSettings, ivec2(2, 3), 0).r;
  p_tmMoss = texelFetch(lookSettings, ivec2(3, 3), 0).r;
  t_col = 2;
  t_nrm = 3;
  t_rough = 4;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

  vec2 tuv = uv * p_repeat;
  k.colour = picColour(t_col, tuv, p_repeat);
  k.nts = picData(t_nrm, tuv, p_repeat).xyz * 2.0 - 1.0;
  k.rough = picData(t_rough, tuv, p_repeat).r;
  ruWear(s2.w, wp, wn, p_tmRot, p_tmChar, p_tmMoss, k.colour, k.rough, k.height);

}

void look_5(inout Look k) {

  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float tarnish = smoothstep(0.5, 0.85, kfbm(uv * 2.5 + seed));
    vec3 c = mix(vec3(0.82, 0.62, 0.25), vec3(0.4, 0.3, 0.14), tarnish);
    k.colour = c;
    k.metal = mix(0.55, 0.35, tarnish);
    k.rough = mix(0.18, 0.5, tarnish);

}

void look_6(inout Look k) {

  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float patina = smoothstep(0.55, 0.85, kfbm(uv * 2.2 + seed)) * (0.5 + 0.5 * smoothstep(0.0, 0.8, wn.y));
    float tone = kfbm(uv * 6.0 + seed);
    vec3 c = mix(vec3(0.72, 0.36, 0.22), vec3(0.5, 0.22, 0.14), tone * 0.6);
    k.colour = mix(c, vec3(0.3, 0.58, 0.48), patina);
    k.metal = mix(0.55, 0.0, patina);
    k.rough = mix(0.25, 0.9, patina);
    k.height = 0.0005 * patina;

}

void look_7(inout Look k) {
  p_wdLight = texelFetch(lookSettings, ivec2(0, 7), 0).rgb;
  p_wdDark = texelFetch(lookSettings, ivec2(1, 7), 0).rgb;
  p_wdRings = texelFetch(lookSettings, ivec2(2, 7), 0).r;
  p_wdFibreBase = texelFetch(lookSettings, ivec2(3, 7), 0).r;
  p_wdFibreAmp = texelFetch(lookSettings, ivec2(4, 7), 0).r;
  p_wdFleck = texelFetch(lookSettings, ivec2(5, 7), 0).r;
  p_wdPores = texelFetch(lookSettings, ivec2(6, 7), 0).r;
  p_wdRough = texelFetch(lookSettings, ivec2(7, 7), 0).r;
  p_wdRelief = texelFetch(lookSettings, ivec2(8, 7), 0).r;
  p_wdFibreRelief = texelFetch(lookSettings, ivec2(9, 7), 0).r;
  p_wdCoat = texelFetch(lookSettings, ivec2(10, 7), 0).r;
  p_wdCoatRough = texelFetch(lookSettings, ivec2(11, 7), 0).r;
  p_wdSplash = texelFetch(lookSettings, ivec2(12, 7), 0).r;
  p_wdSplashColour = texelFetch(lookSettings, ivec2(13, 7), 0).rgb;
  p_wdTread = texelFetch(lookSettings, ivec2(14, 7), 0).r;
  p_wdRot = texelFetch(lookSettings, ivec2(15, 7), 0).r;
  p_wdChar = texelFetch(lookSettings, ivec2(16, 7), 0).r;
  p_wdMoss = texelFetch(lookSettings, ivec2(17, 7), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float r = kring(uv, seed, p_wdRings);
    float fleck = p_wdFleck * smoothstep(0.82, 0.95, kn(vec2(uv.x * 30.0, uv.y * 3.0) + seed)) * kfade(0.008);
    float pores = p_wdPores * smoothstep(0.75, 0.9, kn(vec2(uv.x * 80.0, uv.y * 500.0) + seed)) * r * kfade(0.002);
    float fb = kfibre(uv, seed);
    vec3 c = mix(p_wdLight, p_wdDark, r) * (p_wdFibreBase + p_wdFibreAmp * fb);
    k.colour = mix(c, c * 1.25, fleck) * (1.0 - 0.3 * pores);
    k.rough = p_wdRough + 0.15 * pores;
    k.height = -p_wdRelief * r - 0.0003 * pores + p_wdFibreRelief * fb;
    // splashes: drops of mortar or paint, a few big ones and their spatter round them, a little proud of the face
    if (p_wdSplash > 0.0) {
      float wdId, wdE;
      float wdD = kvor(uv * 9.0 + seed * 2.3, wdId, wdE);
      float wdR = 0.1 + 0.2 * kh1(wdId * 13.0);
      // a splash's ragged outline: its edge pushed in and out by noise as big as itself and finer
      float wdRag = 0.22 * (kfbm4(uv * 40.0 + seed) - 0.5) + 0.1 * (kn(uv * 160.0 + seed + 2.0) - 0.5);
      float wdBlob = step(wdId, p_wdSplash) * (1.0 - smoothstep(wdR - 0.015, wdR + 0.015, wdD + wdRag));
      float wdSId, wdSE;
      float wdSD = kvor(uv * 70.0 + seed * 5.1, wdSId, wdSE);
      float wdSpat = step(wdSId, p_wdSplash * 0.35) * (1.0 - smoothstep(0.08, 0.14, wdSD + 0.08 * (kn(uv * 500.0 + seed) - 0.5))) * kfade(0.012);
      float wdSp = max(wdBlob, wdSpat);
      k.colour = mix(k.colour, p_wdSplashColour * (0.85 + 0.3 * kn(uv * 140.0 + seed + 1.0)), wdSp);
      k.rough = mix(k.rough, 0.95, wdSp);
      k.height += wdSp * (0.0002 + 0.00015 * kn(uv * 300.0 + seed + 4.0));
    }
    // boots' wear: the face rubbed paler and smoother in soft tracks running along the board (u)
