    float id = floor(s3.x / p_rgWidth);
    vec2 q = vec2(fract(s3.x / p_rgWidth), (s3.y - 0.5) / p_rgFill + 0.5);
    // a margin round each rune inside its box
    vec2 r = (q - 0.15) / 0.7;
    float inside = step(0.0, r.x) * step(r.x, 1.0) * step(0.0, r.y) * step(r.y, 1.0);
    float d = rgRune(clamp(r, 0.0, 1.0), id);
    float cut = inside * (1.0 - smoothstep(p_rgStroke * 0.7, p_rgStroke, d)) * kfade(p_rgWidth * p_rgStroke * 2.0);
    float any = step(1e-5, abs(s3.x) + abs(s3.y) + abs(s2.x));
    cut *= any;
    float rock = 0.8 + 0.3 * kfbm(uv * 6.0 + seed);
    k.colour = mix(p_rgStone * rock, p_rgGlow * 0.12, cut);
    k.glow = p_rgGlow * cut * clamp(s2.x, 0.0, 1.0) + p_rgGlow * 0.06 * clamp(s2.x, 0.0, 1.0) * inside * any;
    k.rough = mix(0.85, 0.5, cut);
    k.height = -0.002 * cut;

