  p_hbTin = texelFetch(lookSettings, ivec2(6, 21), 0).r;
  p_hbTinWear = texelFetch(lookSettings, ivec2(7, 21), 0).r;
  p_hbRough = texelFetch(lookSettings, ivec2(8, 21), 0).r;
