  p_recess = texelFetch(lookSettings, ivec2(14, 0), 0).r;
  p_valueVar = texelFetch(lookSettings, ivec2(15, 0), 0).r;
  p_warm = texelFetch(lookSettings, ivec2(16, 0), 0).r;
