  p_fleck = texelFetch(lookSettings, ivec2(18, 0), 0).r;
  p_polish = texelFetch(lookSettings, ivec2(19, 0), 0).r;
  p_dirt = texelFetch(lookSettings, ivec2(20, 0), 0).r;
  p_mossCover = texelFetch(lookSettings, ivec2(21, 0), 0).r;
  p_mossTop = texelFetch(lookSettings, ivec2(22, 0), 0).r;
  p_mossDepth = texelFetch(lookSettings, ivec2(23, 0), 0).r;
  p_mossScale = texelFetch(lookSettings, ivec2(24, 0), 0).r;
  p_wet = texelFetch(lookSettings, ivec2(25, 0), 0).r;
