  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float prW = kweave(uv, p_prThread);
    float prN = kfbm(uv * p_prTarScale + seed);
    float prTar = smoothstep(1.0 - p_prTarAmount - 0.2, 1.0 - p_prTarAmount + 0.2, prN);
    vec3 prDry = p_prFibre * prW * (0.75 + 0.5 * kfbm(uv * 9.0 + seed * 2.0));
    k.colour = mix(prDry, p_prTar * (0.8 + 0.4 * prW), prTar);
    k.rough = mix(0.92, 0.38, prTar);
    k.clearcoat = 0.3 * prTar;
    k.clearcoatRough = 0.25;
    k.height = 0.0004 * (prW - 0.5) * (1.0 - prTar) + 0.0006 * prTar * smoothstep(0.0, 0.3, prN - 0.5);
    k.sheen = p_prFibre * 0.4 * (1.0 - prTar);
    k.sheenRough = 0.8;
    // the embers: thin glowing cracks in the charred cloth, in patches
    float prId, prE;
    kvor(uv * p_prEmberScale + seed * 3.0, prId, prE);
    float prCrack = (1.0 - smoothstep(0.02, 0.14, prE)) * kfade(2.0 / p_prEmberScale);
    float prPatch = smoothstep(1.0 - p_prEmberAmount - 0.1, 1.0 - p_prEmberAmount + 0.1, kfbm(uv * 12.0 + seed * 5.0));
    k.glow = p_prEmber * prCrack * prPatch * (0.6 + 0.4 * prId);
    k.colour = mix(k.colour, vec3(0.02, 0.015, 0.012), prPatch * 0.6);

}

