  p_hsFatAmount = texelFetch(lookSettings, ivec2(4, 35), 0).r;
  p_hsVeins = texelFetch(lookSettings, ivec2(5, 35), 0).r;
  p_hsStrokes = texelFetch(lookSettings, ivec2(6, 35), 0).r;
  p_hsStrokePitch = texelFetch(lookSettings, ivec2(7, 35), 0).r;
  p_hsWet = texelFetch(lookSettings, ivec2(8, 35), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float thick = kfbm(uv * 2.2 + seed);
    float fat = smoothstep(1.0 - p_hsFatAmount, 1.0 - p_hsFatAmount + 0.15, kfbm(uv * 4.5 + seed + 7.0));
    // veins: the thin dark lines where two noises cross their middle, branching as the noise does
    float v1 = abs(kfbm(uv * 5.0 + seed + 3.0) - 0.5);
    float v2 = abs(kfbm(uv * 11.0 + seed + 13.0) - 0.5);
    float vein = (smoothstep(0.018, 0.0, v1) + 0.6 * smoothstep(0.012, 0.0, v2)) * p_hsVeins * kfade(0.01);
    // the scraper's strokes, long and slightly wavering, across u
    float wav = uv.x * p_hsStrokePitch + 1.6 * kfbm(uv * vec2(0.8, 3.0) + seed + 21.0);
    float stroke = (0.5 + 0.5 * sin(wav * 6.28318)) * kfade(1.0 / p_hsStrokePitch);
    vec3 skin = mix(p_hsThin, p_hsSkin, smoothstep(0.3, 0.7, thick));
    skin = mix(skin, p_hsFat, fat * 0.8);
    skin = mix(skin, p_hsVein, clamp(vein, 0.0, 1.0) * 0.7);
    skin *= 0.92 + 0.12 * stroke;
    k.colour = skin;
    k.height = p_hsStrokes * stroke + 0.0008 * (thick - 0.5) + 0.0003 * fat - 0.0002 * vein;
    k.rough = mix(0.82, 0.3, p_hsWet) - 0.1 * fat * p_hsWet;
    k.clearcoat = p_hsWet * (0.6 + 0.4 * fat);
    k.clearcoatRough = 0.15;
    k.sheen = skin * 0.25 * (1.0 - p_hsWet);
    k.sheenRough = 0.7;
    k.ao = 1.0 - 0.25 * vein;

}

void look_36(inout Look k) {
  p_paSteel = texelFetch(lookSettings, ivec2(0, 36), 0).rgb;
  p_paSky = texelFetch(lookSettings, ivec2(1, 36), 0).rgb;
  p_paHorizon = texelFetch(lookSettings, ivec2(2, 36), 0).rgb;
  p_paFloor = texelFetch(lookSettings, ivec2(3, 36), 0).rgb;
  p_paPolish = texelFetch(lookSettings, ivec2(4, 36), 0).r;
  p_paBlur = texelFetch(lookSettings, ivec2(5, 36), 0).r;
  p_paBand = texelFetch(lookSettings, ivec2(6, 36), 0).r;
  p_paWindow = texelFetch(lookSettings, ivec2(7, 36), 0).r;
  p_paLit = texelFetch(lookSettings, ivec2(8, 36), 0).r;
  p_paGlint = texelFetch(lookSettings, ivec2(9, 36), 0).r;
  p_paMetal = texelFetch(lookSettings, ivec2(10, 36), 0).r;
  p_paRough = texelFetch(lookSettings, ivec2(11, 36), 0).r;
  p_paHammer = texelFetch(lookSettings, ivec2(12, 36), 0).r;
  p_paHammerSize = texelFetch(lookSettings, ivec2(13, 36), 0).r;
  p_paScratch = texelFetch(lookSettings, ivec2(14, 36), 0).r;
  p_paTarnish = texelFetch(lookSettings, ivec2(15, 36), 0).r;
  p_paTarnishColour = texelFetch(lookSettings, ivec2(16, 36), 0).rgb;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec3 paN = normalize(wn);
    vec3 paI = normalize(wp - cameraPosition);
    vec3 paR = reflect(paI, paN);
    float paUp = paR.y;
    float paB = p_paBlur;
    // the studio: the floor below, the sky above, a bright band at the horizon, a soft window high to one side
    vec3 paEnv = mix(p_paFloor, p_paSky, smoothstep(-paB, paB, paUp));
    paEnv = mix(paEnv, p_paHorizon, exp(-paUp * paUp / max(0.002, paB * paB * 0.25)) * p_paBand);
    paEnv += vec3(p_paWindow) * smoothstep(0.8, 0.97, dot(paR, normalize(vec3(0.35, 0.85, 0.4))));
    // the planishing hammer's facets: soft shallow dishes, gone to their mean where a pixel is as wide
    float paHf = kfade(1.0 / p_paHammerSize);
    float paH = (kn(uv * p_paHammerSize + seed) * 0.65 + kn(uv * p_paHammerSize * 2.3 + seed * 1.7) * 0.35) * paHf;
    // the polisher's scratches, fine and long
    float paS = kn(vec2(uv.x * 30.0, uv.y * 2400.0) + seed * 2.3) * kfade(0.0008);
    // tarnish in soft drifts, duller and browner
    float paT = p_paTarnish * smoothstep(0.45, 0.8, kfbm(uv * 5.0 + seed * 0.71));
    vec3 paBase = mix(p_paSteel, p_paSteel * p_paTarnishColour / 0.5, paT) * (1.0 - p_paScratch * paS);
    float paMix = p_paPolish * (1.0 - 0.6 * paT);
    vec3 paShown = clamp(paEnv * paBase / 0.65, 0.0, 1.0);
    // what the lights fall on is held down (paLit), or the sun on a plate already carrying its reflection burns it
    // white
    k.colour = mix(paBase * 0.85, paShown, paMix) * p_paLit;
    // a mirror in shade still shows the bright room: that share of the reflection is its own light
    k.glow = paShown * paMix * p_paGlint;
    k.metal = p_paMetal;
    k.rough = clamp(p_paRough + 0.25 * paT + 0.08 * paS, 0.02, 1.0);
    k.height = p_paHammer * paH;

}

